.darma-loader-darma-b15-speed-bag { --accent: var(--loader-color, #a16207); --accent-2: var(--loader-secondary-color, #fbbf24); width: var(--loader-size, 112px); height: calc(var(--loader-size, 112px) * .82); position: relative; }
.darma-loader-darma-b15-speed-bag .darma-loader-darma-b15-speed-bag__board { position: absolute; left: 8%; right: 8%; top: 6%; height: 8%; border-radius: 4px; background: linear-gradient(#64748b, #334155); }
.darma-loader-darma-b15-speed-bag .darma-loader-darma-b15-speed-bag__bag { position: absolute; left: 39%; top: 15%; width: 22%; height: 32%; border-radius: 42% 42% 50% 50%; background: linear-gradient(var(--accent-2), var(--accent)); transform-origin: 50% 0; animation: darma-loader-darma-b15-speed-bag-bag-swing calc(var(--loader-speed, 1s) * .4) ease-in-out infinite; }
.darma-loader-darma-b15-speed-bag .darma-loader-darma-b15-speed-bag__glove { position: absolute; left: 12%; top: 26%; width: 18%; height: 18%; border-radius: 44% 30% 30% 44%; background: linear-gradient(var(--accent), color-mix(in srgb, #000 25%, var(--accent))); animation: darma-loader-darma-b15-speed-bag-bag-hit calc(var(--loader-speed, 1s) * .8) ease-in-out infinite; }
@keyframes darma-loader-darma-b15-speed-bag-bag-swing { 0%, 100% { transform: rotate(-17deg); } 50% { transform: rotate(17deg); } }
@keyframes darma-loader-darma-b15-speed-bag-bag-hit { 0%, 100% { transform: translateX(0) scale(1); } 50% { transform: translateX(72%) scale(1.06); } }

